// Single-block oracle against HuggingFace LlamaAttention / LlamaMLP.
//
// Fixtures (raw binary weights + reference outputs) are generated by:
//   .venv/bin/python tests/python/dump_hf_block_oracle.py \
//       --model /opt/models/Llama-3.2-1B-Instruct --layer 5 --S 8
//   .venv/bin/python tests/python/dump_hf_block_oracle.py \
//       --model /opt/models/Llama-3.2-1B-Instruct --layer 5 --S 1
//
// This tests alice::gpu_rocm blocks against the EXACT submodule classes
// used inside LlamaDecoderLayer, with real model weights and deterministic
// synthetic input.  Because only one block is exercised (no layer-stack
// amplification), the numerical bound is much tighter than the full-model
// canonical gate.

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <string>
#include <vector>

#include <gtest/gtest.h>
#include <hip/hip_runtime_api.h>
#include <nlohmann/json.hpp>

#include "alice/engine_config.hpp"
#include "alice/tensor.hpp"
#include "../src/blocks/gpu_rocm/dense_ffn.hpp"
#include "../src/blocks/gpu_rocm/gqa_attention.hpp"
#include "../src/blocks/gpu_rocm/platform.hpp"
#include "../src/manifest.hpp"

namespace {

using alice::bf16;
using alice::EngineConfig;
using alice::ModelConfig;
using alice::gpu_rocm::Context;
using alice::TensorView;

std::string fixture_dir(uint32_t S) {
  return std::string(ALICE_SOURCE_DIR) + "/tests/hf_oracle/S" + std::to_string(S);
}

nlohmann::json load_meta(uint32_t S) {
  std::ifstream f(fixture_dir(S) + "/meta.json");
  if (!f) throw std::runtime_error("cannot open meta.json for S=" + std::to_string(S));
  return nlohmann::json::parse(
      std::string((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>()));
}

std::vector<float> read_f32(uint32_t S, const std::string& name, size_t expected_floats) {
  std::string path = fixture_dir(S) + "/" + name;
  std::ifstream f(path, std::ios::binary);
  if (!f) throw std::runtime_error("cannot open " + path);
  std::vector<float> buf(expected_floats);
  f.read(reinterpret_cast<char*>(buf.data()), expected_floats * sizeof(float));
  if (size_t(f.gcount()) != expected_floats * sizeof(float))
    throw std::runtime_error("short read: " + path);
  return buf;
}

std::vector<bf16> read_bf16(uint32_t S, const std::string& name, size_t expected_elems) {
  std::string path = fixture_dir(S) + "/" + name;
  std::ifstream f(path, std::ios::binary);
  if (!f) throw std::runtime_error("cannot open " + path);
  std::vector<uint16_t> bits(expected_elems);
  f.read(reinterpret_cast<char*>(bits.data()), expected_elems * sizeof(uint16_t));
  if (size_t(f.gcount()) != expected_elems * sizeof(uint16_t))
    throw std::runtime_error("short read: " + path);
  std::vector<bf16> out(expected_elems);
  for (size_t i = 0; i < expected_elems; ++i) out[i] = bf16{bits[i]};
  return out;
}

float max_abs_diff(const std::vector<float>& a, const std::vector<float>& b) {
  float m = 0.0f;
  for (size_t i = 0; i < a.size(); ++i) m = std::max(m, std::fabsf(a[i] - b[i]));
  return m;
}

template <typename Block>
std::vector<float> run_gpu_block(Block& b, const std::vector<float>& io, uint32_t S) {
  float* d_io = nullptr;
  if (hipMalloc(&d_io, io.size() * sizeof(float)) != hipSuccess) throw std::bad_alloc();
  if (hipMemcpy(d_io, io.data(), io.size() * sizeof(float), hipMemcpyHostToDevice) !=
      hipSuccess)
    throw std::runtime_error("H2D failed");
  b.forward(d_io, S);
  std::vector<float> out(io.size());
  if (hipMemcpy(out.data(), d_io, io.size() * sizeof(float), hipMemcpyDeviceToHost) !=
      hipSuccess)
    throw std::runtime_error("D2H failed");
  (void)hipFree(d_io);
  return out;
}

float* alloc_prefill_scratch(const ModelConfig& mc, const EngineConfig& ec) {
  float* p = nullptr;
  const size_t bytes = size_t(mc.num_heads) * ec.max_prefill_chunk *
                       ((ec.max_seq_len + 63) / 64) * (mc.head_dim + 2) * sizeof(float);
  if (hipMalloc(&p, bytes) != hipSuccess) throw std::bad_alloc();
  return p;
}

// ---------------------------------------------------------------------------
// Attention helpers
// ---------------------------------------------------------------------------
void run_attention_test(uint32_t S, float tolerance) {
  const std::string dir = fixture_dir(S);
  if (!std::filesystem::exists(dir + "/meta.json"))
    GTEST_SKIP() << "HF oracle fixtures not generated for S=" << S;

  auto meta = load_meta(S);
  const uint32_t d = meta.at("hidden_size").get<uint32_t>();
  const uint32_t qd = meta.at("num_heads").get<uint32_t>() * meta.at("head_dim").get<uint32_t>();
  const uint32_t kvd =
      meta.at("num_kv_heads").get<uint32_t>() * meta.at("head_dim").get<uint32_t>();

  ModelConfig mc;
  mc.hidden_size = d;
  mc.num_heads = meta.at("num_heads").get<uint32_t>();
  mc.num_kv_heads = meta.at("num_kv_heads").get<uint32_t>();
  mc.head_dim = meta.at("head_dim").get<uint32_t>();
  mc.rope_theta = meta.at("rope_theta").get<float>();
  mc.has_rope_scaling = meta.value("has_rope_scaling", false);
  if (mc.has_rope_scaling) {
    const auto& rsj = meta.at("rope_scaling");
    mc.rope_scaling.factor = rsj.at("factor").get<float>();
    mc.rope_scaling.low_freq_factor = rsj.at("low_freq_factor").get<float>();
    mc.rope_scaling.high_freq_factor = rsj.at("high_freq_factor").get<float>();
    mc.rope_scaling.original_max_position_embeddings =
        rsj.at("original_max_position_embeddings").get<uint32_t>();
  }

  EngineConfig ec;
  ec.max_seq_len = 8192;
  ec.max_prefill_chunk = std::max(S, 512u);

  auto wq = read_bf16(S, "attn_wq.bf16", size_t(qd) * d);
  auto wk = read_bf16(S, "attn_wk.bf16", size_t(kvd) * d);
  auto wv = read_bf16(S, "attn_wv.bf16", size_t(kvd) * d);
  auto wo = read_bf16(S, "attn_wo.bf16", size_t(d) * qd);

  auto input = read_f32(S, "input.f32", size_t(S) * d);
  auto want = read_f32(S, "attn_out.f32", size_t(S) * d);

  Context ctx(0);
  alice::gpu_rocm::GqaAttentionBF16 attn(
      TensorView<bf16>(wq.data(), qd, d), TensorView<bf16>(wk.data(), kvd, d),
      TensorView<bf16>(wv.data(), kvd, d), TensorView<bf16>(wo.data(), d, qd), mc, ec,
      ctx, alloc_prefill_scratch(mc, ec));

  auto got = run_gpu_block(attn, input, S);

  const float drift = max_abs_diff(want, got);
  printf("Attention S=%u drift: max|Delta| = %.6f\n", S, drift);
  EXPECT_LT(drift, tolerance) << "attention diverged from HF single-layer oracle";
}

// ---------------------------------------------------------------------------
// FFN helpers
// ---------------------------------------------------------------------------
void run_ffn_test(uint32_t S, float tolerance) {
  const std::string dir = fixture_dir(S);
  if (!std::filesystem::exists(dir + "/meta.json"))
    GTEST_SKIP() << "HF oracle fixtures not generated for S=" << S;

  auto meta = load_meta(S);
  const uint32_t d = meta.at("hidden_size").get<uint32_t>();
  const uint32_t inter = meta.at("intermediate_size").get<uint32_t>();

  ModelConfig mc;
  mc.hidden_size = d;
  mc.intermediate_size = inter;

  EngineConfig ec;
  ec.max_seq_len = 8192;
  ec.max_prefill_chunk = std::max(S, 512u);

  auto gate = read_bf16(S, "ffn_gate.bf16", size_t(inter) * d);
  auto up = read_bf16(S, "ffn_up.bf16", size_t(inter) * d);
  auto down = read_bf16(S, "ffn_down.bf16", size_t(d) * inter);

  auto input = read_f32(S, "input.f32", size_t(S) * d);
  auto want = read_f32(S, "ffn_out.f32", size_t(S) * d);

  Context ctx(0);
  alice::gpu_rocm::DenseFfnBF16 ffn(
      TensorView<bf16>(gate.data(), inter, d), TensorView<bf16>(up.data(), inter, d),
      TensorView<bf16>(down.data(), d, inter), mc, ec, ctx);

  auto got = run_gpu_block(ffn, input, S);

  const float drift = max_abs_diff(want, got);
  printf("FFN S=%u drift: max|Delta| = %.6f\n", S, drift);
  EXPECT_LT(drift, tolerance) << "FFN diverged from HF single-layer oracle";
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------
TEST(HfOracle, AttentionPrefillMatchesHf) { run_attention_test(8, 0.05f); }
TEST(HfOracle, AttentionDecodeMatchesHf) { run_attention_test(1, 0.05f); }
TEST(HfOracle, FfnPrefillMatchesHf) { run_ffn_test(8, 0.05f); }
TEST(HfOracle, FfnDecodeMatchesHf) { run_ffn_test(1, 0.05f); }

}  // namespace
